"use client";
import { useEffect, useState } from "react";
import { Clock, Save } from "lucide-react";
import { api, ApiError } from "@/lib/api-client";
type Hour={dayOfWeek:number;day:string;isOpen:boolean;openTime:string|null;closeTime:string|null};
export default function BusinessHoursPage(){
 const [hours,setHours]=useState<Hour[]>([]); const [loading,setLoading]=useState(true); const [saving,setSaving]=useState(false); const [message,setMessage]=useState<string|null>(null); const [error,setError]=useState<string|null>(null);
 useEffect(()=>{void api.get<{hours:Hour[]}>("/api/store-hours/me").then(r=>setHours(r.hours)).catch(e=>setError(e instanceof ApiError?e.message:"Couldn't load business hours.")).finally(()=>setLoading(false));},[]);
 function update(i:number,patch:Partial<Hour>){setHours(h=>h.map((x,n)=>n===i?{...x,...patch}:x));}
 async function save(){setSaving(true);setError(null);setMessage(null);try{await api.put("/api/store-hours/me",{hours});setMessage("Business hours saved.");}catch(e){setError(e instanceof ApiError?e.message:"Couldn't save business hours.");}finally{setSaving(false);}}
 return <main className="shell py-8"><div className="mx-auto max-w-3xl"><div className="flex items-start gap-3"><span className="grid h-11 w-11 place-items-center rounded-card bg-ember-100 text-ember-700"><Clock className="h-5 w-5"/></span><div><h1 className="text-2xl font-bold text-graphite-900 dark:text-white">Business hours</h1><p className="mt-1 text-sm text-graphite-600 dark:text-graphite-400">Tell customers when your store is normally available. Times use Nigeria time (WAT).</p></div></div>{loading?<p className="mt-8 text-sm">Loading…</p>:<div className="mt-7 space-y-3">{hours.map((h,i)=><div key={h.dayOfWeek} className="rounded-card border border-graphite-200 bg-white p-4 dark:border-graphite-700 dark:bg-graphite-900"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><div className="w-28 font-semibold text-graphite-900 dark:text-white">{h.day}</div><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={h.isOpen} onChange={e=>update(i,{isOpen:e.target.checked})}/><span>{h.isOpen?"Open":"Closed"}</span></label><input type="time" disabled={!h.isOpen} value={h.openTime??""} onChange={e=>update(i,{openTime:e.target.value})} className="rounded-lg border border-graphite-200 px-3 py-2 text-sm dark:border-graphite-700 dark:bg-graphite-950 dark:text-white"/><span className="text-sm text-graphite-400">to</span><input type="time" disabled={!h.isOpen} value={h.closeTime??""} onChange={e=>update(i,{closeTime:e.target.value})} className="rounded-lg border border-graphite-200 px-3 py-2 text-sm dark:border-graphite-700 dark:bg-graphite-950 dark:text-white"/></div></div>)}</div>}{error&&<p className="mt-4 text-sm font-semibold text-ember-700">{error}</p>}{message&&<p className="mt-4 text-sm font-semibold text-verified-700">{message}</p>}<button disabled={loading||saving} onClick={()=>void save()} className="mt-6 inline-flex items-center gap-2 rounded-card bg-ember-600 px-5 py-3 text-sm font-bold text-white disabled:opacity-50"><Save className="h-4 w-4"/>{saving?"Saving…":"Save business hours"}</button></div></main>;
}